import pandas as pd

def compute_feature(trans, account):
    merged = pd.merge(trans, account, left_on='account_id', right_on='account_id')
    filtered = merged[(merged['date_y'] < '1997-01-01') & (merged['amount'] > 3000)]
    feature = filtered['account_id'].unique()
    return pd.Series(index=feature, name='account_id', dtype=int)

import pandas as pd

def count_accounts_in_pisek(district, account):
    district = district[district['A2'] == 'Pisek']
    result = pd.merge(district, account, left_on='district_id', right_on='district_id')
    return result.shape[0]

# Alternatively, using vectorized operations
def count_accounts_in_pisek_vectorized(district, account):
    mask = district['A2'] == 'Pisek'
    return mask.sum()

import pandas as pd

def compute_feature(card, disp):
    card = card.merge(disp, left_on='disp_id', right_on='disp_id')
    card = card[card['type_x'] == 'Gold']
    account_ids = card['account_id'].unique()
    return pd.Series(account_ids, index=['gold_accounts'])

import pandas as pd

def compute_feature(card, disp):
    merged = pd.merge(card, disp, left_on='disp_id', right_on='disp_id')

    gold_cards_before_1998 = (merged[merged['type_x'] == 'Gold'][
        merged['issued_x'].apply(lambda x: int(x[:4])) < 1998]).shape[0]

    total_gold_cards = merged[merged['type_x'] == 'Gold'].shape[0]

    if total_gold_cards == 0:
        return 0
    else:
        return (gold_cards_before_1998 / total_gold_cards) * 100

import pandas as pd

def compute_feature():
    account = pd.merge(account, disp, left_on='account_id', right_on='account_id', suffixes=('', '_disp'))

    account['loan_amount'] = account['amount'] * account['rate']

    owner = account.loc[account['loan_amount'].idxmax()]

    return owner['client_id'].tolist()

import pandas as pd

def compute_feature(card, disp):
    result = pd.merge(card, disp, left_on='disp_id', right_on='disp_id', how='inner')
    result = result[result['type_x'] == 'junior']
    result = result[result['issued_y'] > 1996]
    return result['client_id'].unique()

