import pandas as pd

def compute_feature_card_type(client, disp):
    merged = pd.merge(client, disp, left_on='client_id', right_on='client_id')

    result = merged[merged['type'] == 'Credit Card']

    if not result.empty:
        return result['type'].iloc[0]
    else:
        return None

